  "testability": {
    "p_testable": 0.4,
    "blocking_constraints": [
      {
        "code": "LABEL_ERROR",
        "text": "Play-type labels (especially inferred ones) are known to have foul-leakage and misclassification artifacts that can create spurious variation in per-possession PPP, making it hard to attribute any observed difference to the play type itself."
